const esbuild = require('esbuild');
const fs = require('node:fs');
const path = require('node:path');
const destination = path.resolve(__dirname, '../../Easydict/Swift/Feature/Math');
esbuild.buildSync({
    entryPoints: [path.join(__dirname, 'entry.cjs')],
    bundle: true,
    platform: 'browser',
    format: 'iife',
    target: 'safari16',
    minify: true,
    legalComments: 'inline',
    outfile: path.join(destination, 'mathjax-tex-svg.js'),
    banner: { js: '/* MathJax 4.1.3, Apache-2.0. Generated by BuildTools/MathJax; see MathJax-LICENSE.txt. */' }
});
fs.copyFileSync(path.join(__dirname, 'node_modules/@mathjax/src/LICENSE'), path.join(destination, 'MathJax-LICENSE.txt'));
